    h=len(g); w=len(g[0])
    seen=[[False]*w for _ in range(h)]
    out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; lab=set([(i,j)]); seen[i][j]=True
                while st:
                    y,x=st.pop()
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
